export const statusOf=l=>l.status||({'Live Initials':'Initial','Contacting':'Initial','Qualified':'Verified','Won':'Booked','Lost':'Not Interested'}[l.stage]||l.stage);
const f=(key,label,type='text',required=true,choices=[])=>({key,label,type,required,choices});
