  const l=s.leads.find(l=>l.id===action.leadId);required(l,'Lead not found.');required(!s.inventory.some(p=>p.origin?.kind==='Lead'&&p.origin.id===l.id),'Inventory is already linked to this lead.');const saved=applyCRM(s,{type:'recordSave',module:'inventory',data:{...d,seller:l.name,owner:l.owner,status:'Available'}},now,actor);const inv=saved.state.inventory.find(x=>x.id===saved.resultId);inv.origin={kind:'Lead',id:l.id};return saved;
